import {
  RELAY_COLLECTION,
  RELAY_DOC_ID,
  type TurnKey,
} from '@wolsok/feat-shared-bacteria-engine/cloud';
import { type Firestore, Timestamp } from 'firebase-admin/firestore';
import { RELAY_TTL_S } from '../config';
import { fetchRelay } from './fetch-relay';

/**
 * Fresh credentials for the TURN relay into `relay/turn` (ADR 0020), valid
 * {@link RELAY_TTL_S} from `now`: what `refreshRelay` runs every 30
 * minutes, so a reader always gets half of that at least. Throws when
 * Cloudflare refuses, leaving the last credentials until they expire.
 */
export async function refreshRelay(
  db: Firestore,
  key: TurnKey,
  fetchFn: typeof fetch,
  now: number
): Promise<{ expireAt: number }> {
  const entry = await fetchRelay(key, RELAY_TTL_S, fetchFn);
  const expireAt = now + RELAY_TTL_S * 1000;
  await db
    .collection(RELAY_COLLECTION)
    .doc(RELAY_DOC_ID)
    .set({
      ...entry,
      expireAt: Timestamp.fromMillis(expireAt),
      refreshedAt: Timestamp.fromMillis(now),
    });
  return { expireAt };
}
import {
  type RelayEntry,
  relayCredentialsUrl,
  relayEntry,
  type TurnKey,
} from '@wolsok/feat-shared-bacteria-engine/cloud';

/** The longest wait for Cloudflare's answer. */
const FETCH_TIMEOUT_MS = 10_000;

/**
 * Fresh credentials for the relay, valid `ttlSeconds` - throws when
 * Cloudflare refuses or answers no TURN server, never with the token or
 * Cloudflare's text in the message.
 */
export async function fetchRelay(
  key: TurnKey,
  ttlSeconds: number,
  fetchFn: typeof fetch
): Promise<RelayEntry> {
  const response = await fetchFn(relayCredentialsUrl(key.id), {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${key.token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ ttl: ttlSeconds }),
    signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(
      `Cloudflare refused the TURN credentials (${response.status}).`
    );
  }
  // Its own text, never the body's, which a SyntaxError would quote.
  const answer: unknown = await response.json().catch(() => {
    throw new Error('Cloudflare answered no JSON.');
  });
  const entry = relayEntry(answer);
  if (entry === null) {
    throw new Error('Cloudflare answered no TURN server.');
  }
  return entry;
}
import type { RelayServer } from '../storage/game-relay';

/**
 * Public STUN servers, which tell a device the address the internet sees it
 * under. Two devices behind strict NATs - some mobile networks, some
 * Wi-Fi networks - cannot reach each other that way; for them the
 * connection goes through the TURN relay (ADR 0020), and without one they
 * are told so.
 */
const STUN_SERVERS: RTCIceServer[] = [
  { urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] },
];

/** The servers a connection reaches the other device through. */
export function iceServers(relay: readonly RelayServer[]): RTCIceServer[] {
  return [...STUN_SERVERS, ...relay];
